layers.vertex:
attribute vec3 aO; attribute float aT; attribute vec2 aK; uniform float uTime; varying vec2 vP; varying float vU, vK, vN;
    void main(){
      float u = uTime - aT; float life = aK.x < .5 ? .14 : (aK.x < 1.5 ? .3 : .6);
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.3;
      float S = aK.x < .5 ? .5 : (aK.x < 1.5 ? .55 : .3); mv.xy += position.xy*S; vP = position.xy*S; vU = u; vK = aK.x; vN = aK.y;
      gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK, vN; float stroke(float d, float w){ return exp(-(d*d)/(w*w)) + .28*exp(-(d*d)/(w*w*22.)); }
  float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float seg(vec2 p, vec2 a, vec2 b){ vec2 pa = p-a, ba = b-a; float h = clamp(dot(pa,ba)/dot(ba,ba), 0., 1.); return length(pa - ba*h); }
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
      if (vK < .5){
        // impact: thin four-point star, grows and vanishes in ~140 ms
        float t = vU/.14, L = .08 + .32*sqrt(t);
        float d = min(seg(p, vec2(-L,0.), vec2(L,0.)), seg(p, vec2(0.,-L*.55), vec2(0.,L*.55)));
        float f = 1. - t;
        lum += stroke(d, .006 + .006*f)*f*1.6 + exp(-dot(p,p)*90.)*f*1.4; hot += lcore(d, .003)*f;
      } else if (vK < 1.5) {
        // II payoff (2nd Severing on the same target): the impact becomes two quick crossing cuts â€”
        // drawn in 60 ms, gone by 300 ms. A proc pulse only; the lasting Wounded state is the status cue's job.
        float t = vU/.3, f = pow(1. - smoothstep(.35, 1., t), 1.3);
        float d1 = clamp(t/.12, 0., 1.), d2 = clamp((t - .08)/.12, 0., 1.);
        vec2 a1 = vec2(-.22, .14), b1 = mix(a1, vec2(.22, -.12), d1);
        vec2 a2 = vec2(-.2, -.16), b2 = mix(a2, vec2(.2, .15), d2);
        float s1 = seg(p, a1, b1), s2 = seg(p, a2, b2);
        float tp1 = sin(3.14159*clamp(dot(p - a1, normalize(b1 - a1 + 1e-4))/.5, 0., 1.));   // thin ends, full middle
        float tp2 = sin(3.14159*clamp(dot(p - a2, normalize(b2 - a2 + 1e-4))/.5, 0., 1.));
        lum += (stroke(s1, .004 + .012*tp1)*step(.001, d1) + stroke(s2, .004 + .012*tp2)*step(.001, d2))*f*1.3;
        hot += (lcore(s1, .003)*tp1 + lcore(s2, .003)*tp2)*f*.9;
      } else {
        // sequence mark (same as Severing I): one calligraphic cut + count pips (capacity 2)
        // count is read by shape: 1 = one cut, 2 = two crossed cuts, 3 = crossed cuts inside a circle
        float t = vU/.6, f = 1. - smoothstep(.55, 1., t);
        float d1 = smoothstep(0., .1, t), d2 = smoothstep(.06, .16, t), d3 = smoothstep(.1, .26, t);
        vec2 a1 = vec2(-.1, -.07), b1 = mix(a1, vec2(.1, .07), d1);
        vec2 a2 = vec2(-.1, .07), b2 = mix(a2, vec2(.1, -.07), d2);
        float s1 = seg(p, a1, b1), s2 = seg(p, a2, b2);
        float t1 = sin(3.14159*clamp(dot(p - a1, vec2(.819, .573))/.244, 0., 1.));   // thin ends, full middle
        float t2 = sin(3.14159*clamp(dot(p - a2, vec2(.819, -.573))/.244, 0., 1.));
        float m = stroke(s1, .003 + .009*t1);
        if (vN > 1.5) m = max(m, stroke(s2, .003 + .009*t2));
        if (vN > 2.5){ float r = length(p), ang = atan(p.y, p.x) + 3.14159;
          m = max(m, stroke(abs(r - .155), .0065)*step(ang, d3*6.2832)); }                // circle draws around
        lum += m*f*1.1; hot += (lcore(s1, .003)*t1 + (vN > 1.5 ? lcore(s2, .003)*t2 : 0.))*f*.7;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .65)*hot*1.2;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
